:root {
  color-scheme: dark;
  --ink: #f8f5ff;
  --muted: #aaa5bf;
  --purple: #a78bfa;
  --mint: #81f0c0;
  --panel: #211e39;
  --line: #393550;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin: 0; min-width: 320px; min-height: 100vh; color: var(--ink); background-color: #17152b; background-image: radial-gradient(ellipse at 50% 0%, #30274d 0, transparent 58%), linear-gradient(45deg, transparent 48%, #ffffff06 49%, #ffffff06 51%, transparent 52%); background-size: auto, 24px 24px; font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
.shell { min-height: 100vh; display: grid; place-items: center; padding: 28px 16px; }
.wizard { width: min(100%, 500px); padding: 36px 38px 22px; background: var(--panel); border: 1px solid #48425f; border-radius: 18px; box-shadow: 0 24px 80px #09081799, 0 4px 0 #111025; }
.header { text-align: center; }
.pixel-mark { width: 46px; height: 46px; margin: 0 auto 15px; display: grid; place-items: center; color: #17152b; background: var(--mint); border: 4px solid #b9ffe0; box-shadow: 4px 4px 0 #5da88c; font-size: 24px; }
.eyebrow { margin: 0 0 7px; color: var(--mint); font-size: 12px; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(26px, 6vw, 34px); line-height: 1.15; letter-spacing: -.04em; }
.intro, .step-copy { color: var(--muted); }
.intro { margin: 9px 0 26px; }
.progress-wrap { margin-bottom: 27px; }
.progress-meta { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 9px; color: var(--muted); font-size: 13px; }
#step-label { color: var(--mint); font-weight: 800; letter-spacing: .07em; }
.progress-track { height: 8px; overflow: hidden; background: #393550; border-radius: 20px; }
.progress-fill { display: block; width: 33.333%; height: 100%; background: var(--mint); border-radius: inherit; transition: width .25s ease; }
.step h2 { margin: 0; font-size: 22px; }
.step-copy { margin: 3px 0 21px; }
form label:not(.plan-card) { display: block; margin: 15px 0 7px; font-weight: 650; }
input[type="text"], input[type="email"] { width: 100%; height: 50px; padding: 0 14px; color: var(--ink); background: #19172e; border: 1px solid #514c69; border-radius: 8px; font: inherit; }
input::placeholder { color: #77728e; }
input[type="text"]:focus, input[type="email"]:focus { outline: 3px solid #a78bfa66; border-color: var(--purple); }
.hint { margin: 12px 0 0; color: var(--muted); font-size: 14px; }
.plans { display: grid; gap: 10px; margin: 0; padding: 0; border: 0; }
.plan-card { position: relative; display: flex; align-items: center; gap: 12px; min-height: 70px; padding: 11px 13px; cursor: pointer; background: #19172e; border: 1px solid #514c69; border-radius: 9px; transition: border-color .15s, background .15s, transform .1s; }
.plan-card:hover { border-color: var(--purple); background: #24203e; }
.plan-card:active { transform: translateY(1px); }
.plan-card:has(input:checked) { border-color: var(--mint); background: #213b3a; box-shadow: inset 0 0 0 1px var(--mint); }
.plan-card input { width: 18px; height: 18px; accent-color: var(--mint); }
.plan-icon { display: grid; place-items: center; width: 34px; height: 34px; color: var(--mint); background: #34304d; border-radius: 7px; font-size: 20px; }
.plan-text { display: grid; gap: 1px; }
.plan-text small, .plan-price span { color: var(--muted); font-size: 13px; }
.plan-price { margin-left: auto; font-weight: 750; }
.summary { margin: 0; padding: 2px 16px; background: #19172e; border: 1px solid var(--line); border-radius: 10px; }
.summary div { display: flex; justify-content: space-between; gap: 14px; padding: 13px 0; border-bottom: 1px solid var(--line); }
.summary div:last-child { border: 0; }
.summary dt { color: var(--muted); }
.summary dd { margin: 0; max-width: 65%; overflow-wrap: anywhere; text-align: right; font-weight: 650; }
.form-message { min-height: 22px; margin-top: 8px; color: #ffb4b4; font-size: 14px; }
.actions { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 8px; }
button { min-height: 48px; padding: 0 20px; border: 0; border-radius: 8px; cursor: pointer; font: inherit; font-weight: 750; transition: transform .1s, background .15s, box-shadow .15s; }
button:focus-visible { outline: 3px solid var(--purple); outline-offset: 3px; }
button:active:not(:disabled) { transform: translateY(2px); }
.back-button { color: var(--ink); background: #34304d; }
.back-button:hover { background: #45405f; }
.next-button { margin-left: auto; color: #17152b; background: var(--mint); box-shadow: 0 3px 0 #4f9c7e; }
.next-button:hover:not(:disabled) { background: #a5ffd9; }
.next-button:disabled { color: #858199; background: #3b3851; box-shadow: none; cursor: not-allowed; }
footer { margin-top: 27px; color: #77728e; text-align: center; font-size: 11px; font-weight: 750; letter-spacing: .13em; }
footer span { padding: 0 4px; color: var(--mint); }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 420px) { .wizard { padding: 27px 20px 19px; } .progress-meta { font-size: 12px; } .plan-card { gap: 8px; padding-inline: 9px; } .plan-icon { width: 30px; height: 30px; } }

const form = document.querySelector('#signup-form');
const steps = [...document.querySelectorAll('.step')];
const nextButton = document.querySelector('#next');
const backButton = document.querySelector('#back');
const confirmButton = document.querySelector('#confirm');
const message = document.querySelector('#message');
const progress = document.querySelector('#progress');
const progressFill = document.querySelector('#progress-fill');
const stepLabel = document.querySelector('#step-label');
const stepName = document.querySelector('#step-name');
let currentStep = 0;
const names = ['Your details', 'Choose a plan', 'Review'];

function isValid() {
  if (currentStep === 0) {
    const name = document.querySelector('#name');
    const email = document.querySelector('#email');
    return name.value.trim().length >= 2 && email.validity.valid && email.value.trim() !== '';
  }
  if (currentStep === 1) return Boolean(form.querySelector('input[name="plan"]:checked'));
  return true;
}

function update() {
  steps.forEach((step, index) => { step.hidden = index !== currentStep; });
  nextButton.hidden = currentStep === 2;
  confirmButton.hidden = currentStep !== 2;
  backButton.hidden = currentStep === 0;
  nextButton.disabled = !isValid();
  stepLabel.textContent = `STEP ${currentStep + 1} OF 3`;
  stepName.textContent = names[currentStep];
  progress.setAttribute('aria-valuenow', String(currentStep + 1));
  progressFill.style.width = `${((currentStep + 1) / 3) * 100}%`;
  message.textContent = '';
  if (currentStep === 2) {
    document.querySelector('#summary-name').textContent = document.querySelector('#name').value.trim();
    document.querySelector('#summary-email').textContent = document.querySelector('#email').value.trim();
    document.querySelector('#summary-plan').textContent = form.querySelector('input[name="plan"]:checked').value;
  }
}

form.addEventListener('input', () => { nextButton.disabled = !isValid(); });
form.addEventListener('change', () => { nextButton.disabled = !isValid(); });
nextButton.addEventListener('click', () => {
  if (!isValid()) return;
  currentStep += 1;
  update();
  const heading = steps[currentStep].querySelector('h2');
  heading.setAttribute('tabindex', '-1');
  heading.focus();
});
backButton.addEventListener('click', () => {
  currentStep -= 1;
  update();
  steps[currentStep].querySelector('h2').focus();
});
form.addEventListener('submit', event => {
  event.preventDefault();
  if (currentStep !== 2) return;
  message.style.color = 'var(--mint)';
  message.textContent = 'You’re all set — welcome to Pixel Club!';
  confirmButton.disabled = true;
});
update();
